class IGOWidget
{
protected:
    bool display;
public:
    virtual ~IGOWidget();
    virtual void SetDisplay(const bool d = true);
    virtual void Update(const float dt);
    virtual void Draw(void);
    virtual bool GetDisplay(void) const;
};

class PanelQuad;
class TextString;

class WaveIndicatorWidget : public IGOWidget
{
public:
    enum STATE
    {
        STATE_NONE,
        STATE_DIR,
        STATE_SURGE,
        STATE_TONGUE,
        STATE_HILITE_NONE,
        STATE_HILITE_FACE,
        STATE_HILITE_LIP,
        STATE_HILITE_TUBE,
    };
private:
    enum { NUM_WAVES = 3 };
    enum { NUM_TONGUES = 6 };
    static const float TIME_FADE;
    static const float TIME_TUTORIAL_FADE;
    static const float TIME_ANIMATE;
    static const float SPEED_HILITE_FLASH;
    PanelQuad *wavePQ[2][NUM_WAVES];
    PanelQuad *arrowPQ[2];
    PanelQuad *tonguePQ[2][NUM_TONGUES];
    PanelQuad *hilitePQ[2][3];
    PanelQuad *heightPQ;
    TextString *heightText;
    TextString *unitText;
    TextString *nextHeightText;
    TextString *nextUnitText;
    int dirIdx;
    float waveIdx;
    float tongueIdx;
    float hiliteTime;
    float fade;
    int fadeDir;
    STATE state;
public:
    ~WaveIndicatorWidget();
    void SetDisplay(const bool d = true);
    void Update(const float dt);
    void Draw(void);
};

const float WaveIndicatorWidget::TIME_FADE = 4.0f;
const float WaveIndicatorWidget::TIME_TUTORIAL_FADE = 1.0f;
const float WaveIndicatorWidget::TIME_ANIMATE = 0.5f;
const float WaveIndicatorWidget::SPEED_HILITE_FLASH = 2.0f;

__asm__(".equ Update__9IGOWidgetf, 0x00164660");

void WaveIndicatorWidget::Update(const float dt)
{
    IGOWidget::Update(dt);

    if (state != STATE_NONE)
    {
        if (state == STATE_HILITE_FACE || state == STATE_HILITE_LIP || state == STATE_HILITE_TUBE)
            fade += (dt/TIME_TUTORIAL_FADE)*float(fadeDir);
        else
            fade += (dt/TIME_FADE)*float(fadeDir);
        if (fade >= 1.0f)
            fade = 1.0f;
        if (fade <= 0.0f)
        {
            fade = 0.0f;
            state = STATE_NONE;
        }

        if (state == STATE_SURGE)
        {
            waveIdx += dt/TIME_ANIMATE;
            if (int(waveIdx) >= NUM_WAVES)
                waveIdx = 0;
        }
        else if (state == STATE_TONGUE)
        {
            tongueIdx += dt/TIME_ANIMATE;
            if (int(tongueIdx) >= NUM_TONGUES)
                tongueIdx = 0;
        }

        if (state == STATE_HILITE_FACE || state == STATE_HILITE_LIP || state == STATE_HILITE_TUBE)
            hiliteTime += dt;
    }
}
